import { mkdtempSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { chromium } from '/home/ian/.local/share/mise/installs/npm-playwright/1.63.0/node_modules/playwright/index.js'

const dir = mkdtempSync(join(tmpdir(), 'hello-pagehide-'))
const dataFile = join(dir, 'hello.json')
const port = 3101
const child = spawn(process.execPath, ['main.js'], {
  cwd: '/home/ian/hello-world',
  env: { ...process.env, PORT: String(port), DATA_FILE: dataFile },
  stdio: ['ignore', 'pipe', 'pipe'],
})
let browser
try {
  await new Promise((resolve, reject) => {
    child.stdout.on('data', (data) => {
      if (data.toString().includes('Editing at')) resolve()
    })
    child.once('exit', (code) => reject(new Error(`server exited ${code}`)))
  })
  browser = await chromium.launch({ headless: true })
  const page = await browser.newPage()
  const saves = []
  await page.exposeFunction('recordSave', (keepalive) => saves.push(keepalive))
  await page.addInitScript(() => {
    const realFetch = window.fetch
    window.fetch = (input, init = {}) => {
      if (input === '/api/text' && init.method === 'PUT') {
        window.recordSave(Boolean(init.keepalive))
        if (!init.keepalive) {
          return new Promise((resolve, reject) => {
            setTimeout(() => realFetch(input, init).then(resolve, reject), 1500)
          })
        }
      }
      return realFetch(input, init)
    }
  })
  await page.goto(`http://127.0.0.1:${port}`)
  await page.locator('#text').fill('pagehide text')
  await page.locator('#text').evaluate((element) => element.blur())
  await page.evaluate(() => window.dispatchEvent(new PageTransitionEvent('pagehide')))
  await page.waitForFunction(() => false, null, { timeout: 100 }).catch(() => {})
  if (saves.length < 2 || saves[0] !== false || saves[1] !== true) {
    throw new Error(`expected blur save then keepalive pagehide save; got ${JSON.stringify(saves)}`)
  }
  await page.waitForFunction(async () => (await fetch('/api/text')).json().then((x) => x.text === 'pagehide text'))
  if (readFileSync(dataFile, 'utf8') !== 'pagehide text') throw new Error('raw file did not contain saved text')
  console.log(`PASS blur in-flight followed by pagehide issued saves: ${JSON.stringify(saves)}`)
  console.log(`PASS raw artifact: ${JSON.stringify(readFileSync(dataFile, 'utf8'))}`)
} finally {
  await browser?.close()
  child.kill('SIGTERM')
  await new Promise((resolve) => child.once('exit', resolve))
  rmSync(dir, { recursive: true, force: true })
}

