import { spawn } from 'node:child_process'
import net from 'node:net'
import { mkdtempSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { pathToFileURL } from 'node:url'

const REPO = '/home/ian/hello-world'
const PORT = 3100
const URL = `http://127.0.0.1:${PORT}`
const SHOTS = '/tmp/hello-shots'
const WORK = mkdtempSync(join(tmpdir(), 'hello-e2e-'))
const DATA_FILE = join(WORK, 'data', 'hello.json')

const mod = await import(
  pathToFileURL('/home/ian/.local/share/mise/installs/npm-playwright/1.63.0/node_modules/playwright/index.js').href
)
const { chromium } = mod.default ?? mod

const results = []
const consoleMessages = []
const pageErrors = []
const dialogs = []
let serverLog = ''

function check(name, ok, detail = '') {
  results.push({ name, ok, detail })
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? ` — ${detail}` : ''}`)
}
function fatal(name, error) {
  check(name, false, String(error?.stack ?? error))
}

function track(page) {
  page.on('console', (msg) => {
    const entry = `[${msg.type()}] ${msg.text()}`
    consoleMessages.push(entry)
  })
  page.on('pageerror', (error) => pageErrors.push(String(error)))
  page.on('dialog', async (dialog) => {
    dialogs.push(dialog.message())
    await dialog.dismiss()
  })
  return page
}

let proc = null
async function startServer() {
  proc = spawn(process.execPath, ['main.js'], {
    cwd: REPO,
    env: { ...process.env, PORT: String(PORT), DATA_FILE },
    stdio: ['ignore', 'pipe', 'pipe'],
  })
